<?php if (!defined('__TYPECHO_ROOT_DIR__')) exit; ?><!doctype html><html lang="zh-CN"><head><script>(function(){var t='light';try{var s=localStorage.getItem('dl-theme');if(s==='dark'||s==='light'){t=s;}else if(window.matchMedia&&matchMedia('(prefers-color-scheme: dark)').matches){t='dark';}}catch(e){}document.documentElement.setAttribute('data-theme',t);})();</script><meta charset="<?php $this->options->charset(); ?>"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="format-detection" content="telephone=no,email=no,address=no"><meta name="color-scheme" content="light dark"><title><?php $this->archiveTitle('', '', ' - '); ?><?php $this->options->title(); ?></title><?php $dlDesc='';if($this->is('single')){$dlDesc=theme_text_excerpt($this,200);}if(''===$dlDesc){ob_start();$this->options->description();$dlDesc=ob_get_clean();}ob_start();$this->archiveTitle('','',' - ');$this->options->title();$dlTitle=ob_get_clean();ob_start();if($this->is('single')){$this->permalink();}else{$this->options->siteUrl();}$dlUrl=ob_get_clean();$dlType=$this->is('single')?'article':'website';$dlEsc=function($s){return htmlspecialchars($s,ENT_QUOTES,'UTF-8');};ob_start();$this->options->title();$dlSite=ob_get_clean();ob_start();$this->options->logoUrl();$dlLogo=ob_get_clean(); ?><meta name="description" content="<?php echo $dlEsc($dlDesc); ?>"><meta property="og:title" content="<?php echo $dlEsc($dlTitle); ?>"><meta property="og:description" content="<?php echo $dlEsc($dlDesc); ?>"><meta property="og:type" content="<?php echo $dlEsc($dlType); ?>"><meta property="og:url" content="<?php echo $dlEsc($dlUrl); ?>"><meta property="og:site_name" content="<?php echo $dlEsc($dlSite); ?>"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="<?php echo $dlEsc($dlTitle); ?>"><meta name="twitter:description" content="<?php echo $dlEsc($dlDesc); ?>"><?php if(''!==$dlLogo): ?><meta property="og:image" content="<?php echo $dlEsc($dlLogo); ?>"><?php endif; ?><link rel="icon" href="<?php $this->options->themeUrl('favicon.ico'); ?>"><link rel="stylesheet" href="<?php $this->options->themeUrl('style.css?v=20261025t'); ?>"><?php /* 核心 header() 本就会输出 description 与整套 OG/Twitter 标签；主题的版本更长且清过短代码残留，故用规则参数关掉核心的那两组，避免重复 */ $this->header('description=&social='); ?></head><body><div class="site-shell"><header class="site-header"><div class="brand-bar"><div class="site-identity"><h1><a href="<?php $this->options->siteUrl(); ?>"><?php $this->options->title(); ?></a></h1><p><?php $this->options->description(); ?></p></div><span id="bulb"></span><span id="bulbHit" role="button" tabindex="0" title="切换深色 / 浅色" aria-label="切换深色或浅色模式"></span></div><nav class="site-nav"><div class="nav-panel"><ul><li><a<?php if($this->is('index')): ?> class="current"<?php endif; ?> href="<?php $this->options->siteUrl(); ?>">首页</a></li><?php $dlNavPages = $this->options->navPages; if (!is_array($dlNavPages)) { $dlNavPages = ['ShowArchive', 'ShowTags']; } $this->widget('Widget_Contents_Page_List')->to($pages); while($pages->next()): ?><?php if (('archives' === $pages->slug && !in_array('ShowArchive', $dlNavPages)) || ('tags' === $pages->slug && !in_array('ShowTags', $dlNavPages))) { continue; } ?><li><a<?php if($this->is('page',$pages->slug) || ($this->is('search') && 'search' === $pages->slug)): ?> class="current"<?php endif; ?> href="<?php $pages->permalink(); ?>"><?php $pages->title(); ?></a></li><?php endwhile; ?></ul></div></nav></header><div class="content-wrap"><main class="main-content">
